#include <stdint.h>
#include <stdio.h>

int main(void) {
    uint8_t x = 0x12;     // 00010010 = 18
    uint8_t y = 0xCE;     // 11001110 = 206

    uint8_t a = x & y;
    uint8_t o = x | y;
    uint8_t e = x ^ y;
    uint8_t n = ~x;

    printf("x & y = %3d = 0x%02X\n", a, a);
    printf("x | y = %3d = 0x%02X\n", o, o);
    printf("x ^ y = %3d = 0x%02X\n", e, e);
    printf("~x    = %3d = 0x%02X\n", n, n);
    return 0;
}

#include <stdint.h>
#include <stdio.h>

int main(void) {
    uint8_t x = 23;          // 00010111
    for (int k = 0; k <= 4; k++) {
        uint8_t y = x << k;  // x itself does not change
        printf("x << %d = %3d\n", k, y);
    }
    return 0;
}

#include <stdint.h>
