#include <stdint.h>
#include <stdio.h>

// prints the 8 bits of x, most significant bit first
void printb(uint8_t x) {
    char buf[9];
    for (size_t i = 0; i < 8; i++) {
        uint8_t y = x & (1 << i);             // keep only bit i of x
        buf[7 - i] = (y > 0) ? '1' : '0';     // bit i goes at index 7 - i
    }
    buf[8] = '\0';
    printf("%s\n", buf);
}

int main(void) {
    printb(18);
    printb(206);
    printb(18 & 206);
    printb(23 << 2);
    printb(23 >> 2);
    return 0;
}

#include <stdint.h>
#include <stdio.h>

// prints the 32 bits of x, most significant first, a space after each byte
void printb32(uint32_t x) {
    for (int i = 31; i >= 0; i--) {
        if ((x >> i) & 1u) {
            printf("1");
        }
        else {
            printf("0");
        }
        if (i % 8 == 0 && i > 0) {
            printf(" ");
        }
    }
    printf("\n");
}

int main(void) {
    printb32(1u);
    printb32(0xCAFEu);
    printb32(1u << 31);
    return 0;
}

#include <stdint.h>
#include <stdio.h>

void printb(uint8_t x) {
    char buf[9];
    for (size_t i = 0; i < 8; i++) {
        uint8_t y = x & (1 << i);
        buf[7 - i] = (y > 0) ? '1' : '0';
    }
    buf[8] = '\0';
    printf("%s\n", buf);
}

int main(void) {
    uint8_t x = 0x12;                 // 00010010
    printf("start      ");
    printb(x);

    x = x | (1u << 0);                // set bit 0
    printf("set 0      ");
    printb(x);

    x = x & ~(1u << 4);               // clear bit 4
    printf("clear 4    ");
    printb(x);

    x = x ^ (1u << 7);                // toggle bit 7
    printf("toggle 7   ");
    printb(x);

    printf("bit 1 is %u, bit 2 is %u\n", (x >> 1) & 1u, (x >> 2) & 1u);
    return 0;
}

#include <stdio.h>

int main(void) {
    unsigned int x = 0x0F;    // 00001111
    x |= 0x30;                // same as x = x | 0x30
    printf("%02X\n", x);
    x &= ~0x03u;              // clear the two lowest bits
    printf("%02X\n", x);
    x ^= 0xFF;                // flip the low 8 bits
    printf("%02X\n", x);
    x <<= 1;
    printf("%02X\n", x);
    x >>= 4;
    printf("%02X\n", x);
    return 0;
}

