#include <stdio.h>

int main(void) {
    char word[] = "Hello";
    for (size_t i = 0; word[i] != '\0'; i++) {
        printf("%c", word[i] | 32);    // set bit 5: lowercase
    }
    printf("\n");
    for (size_t i = 0; word[i] != '\0'; i++) {
        printf("%c", word[i] ^ 32);    // toggle bit 5: swap case
    }
    printf("\n");
    printf("%d %d\n", 'A', 'a');
    return 0;
}

