#include <stdio.h>

// returns 1 if bit k of x is 1, otherwise 0
unsigned int test_bit(unsigned int x, int k) {
    return (x >> k) & 1u;
}

// returns x with bit k set to 1
unsigned int set_bit(unsigned int x, int k) {
    return x | (1u << k);
}

// returns x with bit k cleared to 0
unsigned int clear_bit(unsigned int x, int k) {
    return x & ~(1u << k);
}

// returns x with bit k flipped
unsigned int toggle_bit(unsigned int x, int k) {
    return x ^ (1u << k);
}

int main(void) {
    unsigned int x = 0x12;                            // 00010010 = 18
    printf("%u %u\n", test_bit(x, 1), test_bit(x, 2));
    printf("%u\n", set_bit(x, 0));
    printf("%u\n", clear_bit(x, 4));
    printf("%u\n", toggle_bit(x, 7));
    printf("%u\n", x);
    return 0;
}

