#include <stdint.h>
#include <stdio.h>

// returns the index of the lowest bit of x that is 1, or -1 if x is 0
int lowest_set_bit(uint32_t x) {
    for (int k = 0; k < 32; k++) {
        if ((x & (1u << k)) != 0) {
            return k;
        }
    }
    return -1;
}

int main(void) {
    printf("%d\n", lowest_set_bit(0x12));
    printf("%d\n", lowest_set_bit(1));
    printf("%d\n", lowest_set_bit(0x80000000u));
    printf("%d\n", lowest_set_bit(0));
    return 0;
}

#include <stdint.h>
#include <stdio.h>

// returns x with its 8 bits in reverse order: bit 0 swaps with bit 7, bit 1 with bit 6, ...
uint8_t reverse_bits(uint8_t x) {
    uint8_t r = 0;
    for (int i = 0; i < 8; i++) {
        if ((x >> i) & 1u) {
            r = r | (1u << (7 - i));
        }
    }
    return r;
}

int main(void) {
    printf("%d\n", reverse_bits(0x16));   // 00010110 -> 01101000
    printf("%d\n", reverse_bits(1));      // 00000001 -> 10000000
    printf("%d\n", reverse_bits(0xF0));   // 11110000 -> 00001111
    return 0;
}
